sys_ui_script.script:
var OrderClientUtils = OrderClientUtils || {};

  OrderClientUtils.warnIfOpenOrders = function(gForm, itemValue) {
      var ga = new GlideAjax('x_..._orders.OrderAjaxUtils'); // scoped name!
      ga.addParam('sysparm_name', 'getOpenOrderCount');
      ga.addParam('sysparm_item', itemValue);
      ga.getXMLAnswer(function(answer) {              // ASYNC — the only right way
          var n = parseInt(answer, 10);
          if (n > 0) {
              gForm.showFieldMsg('item',
                  n + ' open order(s) already exist for this item', 'warning');
          }
      });
  };
